package eval

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"testing"

	"github.com/btposey/civquest/orchestrator-go/internal/blueprints"
	"github.com/btposey/civquest/orchestrator-go/internal/db"
	civquestv1 "github.com/btposey/civquest/orchestrator-go/internal/proto/v1"
	"github.com/btposey/civquest/orchestrator-go/internal/system1"
	"github.com/btposey/civquest/orchestrator-go/internal/system2"
	"github.com/btposey/civquest/orchestrator-go/internal/xdg"
)

// s2.architect smoke (cq-71l.9): a blueprint generated by the System 2 architect (stub LLM) is
// consumed end to end by the System 1 construction skill, placing every block and registering
// the completed building in the clan civic registry.
func TestArchitectGeneratedBlueprint_BuiltEndToEnd(t *testing.T) {
	llm := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(system2.ChatCompletionResponse{Choices: []system2.ChatCompletionChoice{{
			Message: system2.ChatMessage{Role: system2.RoleAssistant, Content: `{
  "name": "Pioneer Armory Annex", "purpose": "ARMORY",
  "dimensions": {"width": 3, "height": 2, "length": 3, "min_y": 0},
  "palette": {"L": "minecraft:oak_log", "P": "minecraft:spruce_planks"},
  "layers": [
    {"y": 0, "grid": ["LLL", "L.L", "LLL"]},
    {"y": 1, "grid": ["PPP", "P.P", "PPP"]}
  ]}`},
			FinishReason: "stop",
		}}})
	}))
	defer llm.Close()
	client, err := system2.NewClientWithConfig(xdg.LLMGatewayConfig{BaseURL: llm.URL},
		xdg.InferenceGovernorConfig{MaxConcurrentLLMRequests: 1, RequestTimeoutSeconds: 5})
	if err != nil {
		t.Fatal(err)
	}
	defer client.Close()

	bp, err := system2.NewArchitectService(client).GenerateDerivative(context.Background(), &system2.ArchitecturalDerivativeRequest{
		BaseBlueprint: &blueprints.Blueprint{ID: "base", Name: "Base", Purpose: blueprints.PurposeShelter,
			Dimensions: blueprints.Dimensions{Width: 3, Height: 1, Length: 3},
			Palette:    map[int]string{1: "minecraft:oak_log"},
			Layers:     []blueprints.Layer{{Y: 0, Matrix: [][]int{{1, 1, 1}, {1, 0, 1}, {1, 1, 1}}}}},
		ModificationDescription: "Add an armory roof",
	})
	if err != nil {
		t.Fatalf("architect: %v", err)
	}

	tmp := t.TempDir()
	civic, err := db.OpenCivicRegistryDB(filepath.Join(tmp, "civic.db"), "clan_arch")
	if err != nil {
		t.Fatal(err)
	}
	defer civic.Close()
	coord, err := blueprints.NewConstructionCoordinator(blueprints.CoordinatorConfig{
		ProjectID: "proj-architect", Blueprint: bp, AnchorX: 10, AnchorY: 64, AnchorZ: 10, CivicDB: civic})
	if err != nil {
		t.Fatalf("coordinator rejected the architect blueprint: %v", err)
	}
	skill := system1.NewConstructionSkill(coord)

	sim, err := NewTimeWarpSimulation(TimeWarpConfig{AgentID: "alder", ClanID: "clan_arch", WorkDir: tmp, TickDelta: 4,
		InitialPosition: &civquestv1.Vec3{X: 11.5, Y: 64, Z: 11.5},
		InitialInventory: []*civquestv1.ItemStackProto{
			{ItemId: "minecraft:oak_log", Count: 64}, {ItemId: "minecraft:spruce_planks", Count: 64}}})
	if err != nil {
		t.Fatal(err)
	}
	defer sim.Close()

	fg := system1.NewFactGraph()
	fg.SetBool("construction.active", "construction", true, "active build project")
	state := system1.NewAgentState()
	progress := &system1.ConstructionLocal{}
	placed := 0
	for i := 0; i < 200 && !coord.IsComplete(); i++ {
		intents, err := skill.Execute(&system1.SkillContext{AgentID: "alder", Frame: sim.BuildTelemetryFrame(),
			State: state, CivicDB: civic, Construction: progress}, fg)
		if err != nil {
			t.Fatalf("iteration %d: %v", i, err)
		}
		for _, in := range intents {
			if nav := in.GetNavigate(); nav != nil {
				sim.SetPosition(nav.Target.X, nav.Target.Y, nav.Target.Z)
			}
			if ib := in.GetInteractBlock(); ib != nil {
				switch ib.InteractionType {
				case civquestv1.InteractBlockIntent_HARVEST_BREAK:
					delete(sim.blocks, posToKey(ib.Pos))
				case civquestv1.InteractBlockIntent_PLACE_BLOCK:
					placed++
					sim.blocks[posToKey(ib.Pos)] = ib.BlockOrItemId
					sim.RemoveInventoryItem(ib.BlockOrItemId, 1)
				}
			}
		}
		_ = sim.Step(4)
	}

	if !coord.IsComplete() {
		t.Fatalf("architect blueprint not completed (placed %d)", placed)
	}
	if placed != 16 {
		t.Fatalf("expected 16 placed blocks (8 logs + 8 planks), got %d", placed)
	}
	if got := sim.blocks[BlockPosKey{X: 10, Y: 65, Z: 10}]; got != "minecraft:spruce_planks" {
		t.Fatalf("roof corner: got %q", got)
	}
	if zones, err := civic.ListZones(); err != nil || len(zones) == 0 {
		t.Fatalf("completed building must register a civic zone: %v %v", zones, err)
	}
}
